-- MediDrop initial schema (PostgreSQL 16, generated from the verified JPA model)
-- Money columns use numeric(12,2); all timestamps are stored in UTC.
create table addresses (is_default boolean not null, latitude float(53) not null, longitude float(53) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, user_id bigint not null, pincode varchar(10) not null, phone varchar(20) not null, label varchar(40) not null, city varchar(80) not null, state varchar(80) not null, recipient_name varchar(120) not null, line1 varchar(200) not null, line2 varchar(200), primary key (id));
create table audit_logs (actor_user_id bigint, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, actor_role varchar(20), entity_id varchar(60), entity_type varchar(60), ip_address varchar(60), action varchar(80) not null, details varchar(2000), primary key (id));
create table cart_items (quantity integer not null, unit_price_snapshot numeric(12,2), cart_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, inventory_id bigint not null, medicine_id bigint not null, pharmacy_id bigint not null, updated_at timestamp(6) with time zone not null, primary key (id), unique (cart_id, inventory_id));
create table coupons (active boolean not null, max_discount numeric(12,2), min_order_value numeric(12,2) not null, usage_limit integer, used_count integer not null, value numeric(12,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, valid_from timestamp(6) with time zone, valid_to timestamp(6) with time zone, type varchar(10) not null check (type in ('PERCENT','FLAT')), code varchar(40) not null unique, description varchar(200), primary key (id));
create table delivery_assignments (distance_km float(53), estimated_minutes integer, payout integer not null, accepted_at timestamp(6) with time zone, assigned_at timestamp(6) with time zone not null, created_at timestamp(6) with time zone not null, delivered_at timestamp(6) with time zone, id bigint generated by default as identity, order_id bigint not null unique, partner_id bigint not null, picked_up_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, status varchar(30) not null check (status in ('ASSIGNED','ACCEPTED','REJECTED','AT_PHARMACY','PICKED_UP','OUT_FOR_DELIVERY','DELIVERED','FAILED')), rejection_reason varchar(400), primary key (id));
create table delivery_locations (accuracy float(53), heading float(53), latitude float(53) not null, longitude float(53) not null, speed float(53), assignment_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, partner_id bigint not null, updated_at timestamp(6) with time zone not null, primary key (id));
create table delivery_partner_documents (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, partner_id bigint not null, reviewed_at timestamp(6) with time zone, reviewed_by bigint, updated_at timestamp(6) with time zone not null, status varchar(20) not null check (status in ('PENDING','APPROVED','REJECTED','SUSPENDED')), document_type varchar(40) not null, content_type varchar(100) not null, remarks varchar(400), storage_key varchar(400) not null, file_name varchar(255) not null, primary key (id));
create table delivery_partners (bank_account_last4 varchar(4), completed_deliveries integer not null, current_latitude float(53), current_longitude float(53), online boolean not null, rating numeric(3,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, last_location_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, user_id bigint not null unique, payout_ifsc varchar(20), phone varchar(20) not null, status varchar(20) not null check (status in ('PENDING','APPROVED','REJECTED','SUSPENDED')), vehicle_number varchar(30), id_proof_type varchar(40), vehicle_type varchar(40), id_proof_number varchar(60), bank_account_name varchar(120), email varchar(160) not null, full_name varchar(160) not null, address varchar(400) not null, review_note varchar(500), primary key (id));
create table inventory_batches (cost_price numeric(12,2), expiry_date date not null, quantity integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, inventory_id bigint not null, updated_at timestamp(6) with time zone not null, batch_number varchar(60) not null, primary key (id), unique (inventory_id, batch_number));
create table inventory_transactions (balance_after integer not null, quantity_delta integer not null, actor_user_id bigint, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, inventory_id bigint not null, order_id bigint, updated_at timestamp(6) with time zone not null, type varchar(20) not null check (type in ('RESTOCK','SALE','ADJUSTMENT','RETURN','EXPIRY')), reason varchar(300), primary key (id));
create table manufacturers (active boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, name varchar(160) not null unique, website varchar(200), primary key (id));
create table medicine_categories (active boolean not null, display_order integer not null, prescription_only boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, name varchar(80) not null unique, slug varchar(90) not null unique, description varchar(300), primary key (id));
create table medicines (active boolean not null, is_demo boolean not null, prescription_required boolean not null, category_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, manufacturer_id bigint, updated_at timestamp(6) with time zone not null, schedule_class varchar(20), dosage_form varchar(40) not null, strength varchar(60), pack_size varchar(80), brand varchar(160), generic_name varchar(200), name varchar(200) not null, image_url varchar(500), warnings varchar(1000), description varchar(2000), primary key (id));
create table notifications (is_read boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, user_id bigint not null, type varchar(40) not null, title varchar(160) not null, link varchar(400), body varchar(1000) not null, primary key (id));
create table order_items (line_total numeric(12,2) not null, prescription_required boolean not null, quantity integer not null, unit_price numeric(12,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, inventory_id bigint not null, medicine_id bigint not null, order_id bigint not null, updated_at timestamp(6) with time zone not null, medicine_name varchar(200) not null, primary key (id));
create table order_status_history (actor_user_id bigint, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, order_id bigint not null, updated_at timestamp(6) with time zone not null, actor_role varchar(20) check (actor_role in ('CUSTOMER','PHARMACY','DELIVERY','ADMIN')), from_status varchar(40) check (from_status in ('CREATED','PAYMENT_PENDING','PAYMENT_CONFIRMED','PRESCRIPTION_REVIEW_PENDING','PRESCRIPTION_APPROVED','PRESCRIPTION_REJECTED','PHARMACY_ACCEPTED','PREPARING','READY_FOR_PICKUP','DELIVERY_ASSIGNED','PICKED_UP','OUT_FOR_DELIVERY','DELIVERED','CANCELLATION_REQUESTED','CANCELLED','REFUND_PENDING','REFUNDED','FAILED')), to_status varchar(40) not null check (to_status in ('CREATED','PAYMENT_PENDING','PAYMENT_CONFIRMED','PRESCRIPTION_REVIEW_PENDING','PRESCRIPTION_APPROVED','PRESCRIPTION_REJECTED','PHARMACY_ACCEPTED','PREPARING','READY_FOR_PICKUP','DELIVERY_ASSIGNED','PICKED_UP','OUT_FOR_DELIVERY','DELIVERED','CANCELLATION_REQUESTED','CANCELLED','REFUND_PENDING','REFUNDED','FAILED')), reason varchar(500), primary key (id));
create table orders (delivery_fee numeric(12,2) not null, delivery_otp_verified boolean not null, discount numeric(12,2) not null, distance_km float(53), latitude float(53) not null, longitude float(53) not null, prescription_required boolean not null, subtotal numeric(12,2) not null, tax_amount numeric(12,2) not null, total_amount numeric(12,2) not null, cancel_eligible_until timestamp(6) with time zone, created_at timestamp(6) with time zone not null, customer_id bigint not null, delivered_at timestamp(6) with time zone, id bigint generated by default as identity, pharmacy_id bigint not null, placed_at timestamp(6) with time zone not null, prescription_id bigint, updated_at timestamp(6) with time zone not null, pincode varchar(10) not null, payment_method varchar(20) not null, recipient_phone varchar(20) not null, order_number varchar(30) not null unique, coupon_code varchar(40), status varchar(40) not null check (status in ('CREATED','PAYMENT_PENDING','PAYMENT_CONFIRMED','PRESCRIPTION_REVIEW_PENDING','PRESCRIPTION_APPROVED','PRESCRIPTION_REJECTED','PHARMACY_ACCEPTED','PREPARING','READY_FOR_PICKUP','DELIVERY_ASSIGNED','PICKED_UP','OUT_FOR_DELIVERY','DELIVERED','CANCELLATION_REQUESTED','CANCELLED','REFUND_PENDING','REFUNDED','FAILED')), tracking_key varchar(40) unique, city varchar(80) not null, state varchar(80) not null, idempotency_key varchar(100), recipient_name varchar(120) not null, delivery_otp_hash varchar(128), line1 varchar(200) not null, line2 varchar(200), cancellation_reason varchar(500), customer_note varchar(500), primary key (id), constraint uk_order_idempotency unique (idempotency_key));
create table otp_tokens (attempts integer not null, consumed boolean not null, created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, user_id bigint not null, purpose varchar(20) not null, code_hash varchar(128) not null, primary key (id));
create table password_reset_tokens (used boolean not null, created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, user_id bigint not null, token_hash varchar(128) not null unique, primary key (id));
create table payments (amount numeric(12,2) not null, currency varchar(3) not null, is_test boolean not null, signature_verified boolean not null, captured_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, customer_id bigint not null, id bigint generated by default as identity, order_id bigint not null, updated_at timestamp(6) with time zone not null, method varchar(20) check (method in ('UPI','CARD','NETBANKING','WALLET','COD')), provider varchar(30) not null, status varchar(30) not null check (status in ('CREATED','AUTHORIZED','CAPTURED','FAILED','REFUND_PENDING','PARTIALLY_REFUNDED','REFUNDED')), client_reference varchar(100) not null unique, provider_order_id varchar(120) not null unique, provider_payment_id varchar(120), failure_reason varchar(400), primary key (id));
create table pharmacies (accepting_orders boolean not null, active boolean not null, avg_prep_minutes integer not null, delivery_radius_km float(53) not null, latitude float(53) not null, longitude float(53) not null, min_order_value numeric(12,2) not null, rating numeric(3,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, owner_user_id bigint not null unique, updated_at timestamp(6) with time zone not null, pincode varchar(10) not null, gstin varchar(20), phone varchar(20) not null, status varchar(20) not null check (status in ('PENDING','APPROVED','REJECTED','SUSPENDED')), city varchar(80) not null, license_number varchar(80) not null unique, state varchar(80) not null, email varchar(160) not null, name varchar(160) not null, registered_address varchar(400) not null, review_note varchar(500), primary key (id));
create table pharmacy_documents (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, pharmacy_id bigint not null, reviewed_at timestamp(6) with time zone, reviewed_by bigint, updated_at timestamp(6) with time zone not null, status varchar(20) not null check (status in ('PENDING','APPROVED','REJECTED','SUSPENDED')), document_type varchar(40) not null, content_type varchar(100) not null, remarks varchar(400), storage_key varchar(400) not null, file_name varchar(255) not null, primary key (id));
create table pharmacy_inventory (active boolean not null, low_stock_threshold integer not null, mrp numeric(12,2) not null, price numeric(12,2) not null, reserved_quantity integer not null, stock_quantity integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, medicine_id bigint not null, pharmacy_id bigint not null, updated_at timestamp(6) with time zone not null, version bigint not null, primary key (id), unique (pharmacy_id, medicine_id));
create table pharmacy_operating_hours (close_time time(6) not null, closed boolean not null, day_of_week integer not null, open_time time(6) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, pharmacy_id bigint not null, updated_at timestamp(6) with time zone not null, primary key (id), unique (pharmacy_id, day_of_week));
create table prescription_reviews (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, pharmacist_user_id bigint not null, prescription_id bigint not null, reviewed_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, decision varchar(20) not null, comments varchar(500), verified_items varchar(2000), primary key (id));
create table prescriptions (is_demo boolean not null, ocr_confidence numeric(5,2), created_at timestamp(6) with time zone not null, customer_id bigint not null, id bigint generated by default as identity, order_id bigint, pharmacy_id bigint, reviewed_at timestamp(6) with time zone, reviewed_by bigint, size_bytes bigint not null, updated_at timestamp(6) with time zone not null, status varchar(30) not null check (status in ('UPLOADED','UNDER_REVIEW','APPROVED','REJECTED')), content_type varchar(100) not null, storage_key varchar(400) not null unique, notes varchar(500), rejection_reason varchar(500), ocr_extracted_text varchar(4000), file_name varchar(255) not null, primary key (id));
create table refresh_tokens (revoked boolean not null, created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, user_id bigint not null, replaced_by_hash varchar(128), token_hash varchar(128) not null unique, primary key (id));
create table refunds (amount numeric(12,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, order_id bigint not null, payment_id bigint not null, processed_at timestamp(6) with time zone, requested_by bigint, updated_at timestamp(6) with time zone not null, status varchar(30) not null, provider_refund_id varchar(120), reason varchar(300) not null, primary key (id));
create table reviews (rating integer not null, created_at timestamp(6) with time zone not null, customer_id bigint not null, id bigint generated by default as identity, order_id bigint not null unique, pharmacy_id bigint not null, updated_at timestamp(6) with time zone not null, comment varchar(1000), primary key (id));
create table shopping_carts (created_at timestamp(6) with time zone not null, customer_id bigint not null unique, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, primary key (id));
create table support_tickets (created_at timestamp(6) with time zone not null, customer_id bigint not null, id bigint generated by default as identity, order_id bigint, resolved_at timestamp(6) with time zone, resolved_by bigint, updated_at timestamp(6) with time zone not null, status varchar(20) not null, subject varchar(160) not null, message varchar(2000) not null, response varchar(2000), primary key (id));
create table system_settings (is_public boolean not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, setting_key varchar(80) not null, description varchar(300), setting_value varchar(1000) not null, primary key (setting_key));
create table users (email_verified boolean not null, enabled boolean not null, locked boolean not null, phone_verified boolean not null, created_at timestamp(6) with time zone not null, deletion_requested_at timestamp(6) with time zone, id bigint generated by default as identity, last_login_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, phone varchar(20), role varchar(20) not null check (role in ('CUSTOMER','PHARMACY','DELIVERY','ADMIN')), full_name varchar(120) not null, email varchar(160) not null unique, avatar_url varchar(500), password_hash varchar(255) not null, primary key (id));
create index idx_address_user on addresses (user_id);
create index idx_audit_actor on audit_logs (actor_user_id);
create index idx_assignment_partner on delivery_assignments (partner_id);
create index idx_delivery_location_assignment on delivery_locations (assignment_id);
create index idx_inventory_tx_inventory on inventory_transactions (inventory_id);
create index idx_medicine_name on medicines (name);
create index idx_medicine_generic on medicines (generic_name);
create index idx_medicine_category on medicines (category_id);
create index idx_notification_user on notifications (user_id);
create index idx_order_item_order on order_items (order_id);
create index idx_order_history_order on order_status_history (order_id);
create index idx_order_customer on orders (customer_id);
create index idx_order_pharmacy on orders (pharmacy_id);
create index idx_order_status on orders (status);
create index idx_otp_user_purpose on otp_tokens (user_id, purpose);
create index idx_payment_order on payments (order_id);
create index idx_inventory_medicine on pharmacy_inventory (medicine_id);
create index idx_prescription_review_rx on prescription_reviews (prescription_id);
create index idx_prescription_customer on prescriptions (customer_id);
create index idx_refresh_user on refresh_tokens (user_id);
create index idx_refund_order on refunds (order_id);
create index idx_support_customer on support_tickets (customer_id);
